// app.js —— Express + EJS 评论渲染（变体1：变量值经非转义标签输出）
const express = require('express');
const app = express();
app.set('view engine', 'ejs');

// 视图文件 views/comment.ejs 全文（模板源码固定，不拼接用户输入）：
//   <div class="comment-body"><%- userComment %></div>

// 评论渲染接口：GET /comment?text=...
app.get('/comment', function renderComment(req, res) {
  // 外部输入入口：查询参数 text 完全由客户端控制，未做任何过滤或校验
  const userComment = String(req.query.text || '');
  // userComment 仅作为模板变量值（locals）传入，不进入模板源码参与编译
  res.render('comment', { userComment: userComment });
});

app.listen(3000, function () {
  console.log('comment service listening on 3000');
});
```

代码片段（语言: javascript）：
```javascript
// 告警模板编辑器：用户自定义告警通知模板并即时预览
const express = require('express');
const ejs = require('ejs');
const app = express();
app.use(express.json());

// 按渠道保存用户编辑的告警模板
const templateStore = {};

app.post('/alert-template/preview', (req, res) => {
  // 外部输入：编辑器提交的完整模板字符串（允许用户书写 EJS 语法）
  const userTemplate = req.body.template || '';
  const channel = req.body.channel || 'default';
  templateStore[channel] = userTemplate;

  // 渲染上下文：告警元数据（固定值，非攻击路径）
  const alertCtx = { alertName: 'CPU过载', level: 'P1', host: 'node-07' };

  // 危险点：userTemplate 整体被 ejs.render 编译为模板并执行，
  // 其中的 <% %>、<%= %>、<%- %> 定界符都会被当作模板语法运行
  const rendered = ejs.render(userTemplate, alertCtx);
  res.type('text/plain').send(rendered);
});

app.listen(8080, () => console.log('alert editor on 8080'));
```
